pub fn bash_fold_serialize_word_parts_concatenated_from(acc: String, parts: Rc<Vec<Rc<Node>>>, index: i64) -> Rc<Outcome<String>> {
    stacker::maybe_grow(512 * 1024, 2 * 1024 * 1024, || {
        match v1_rt::list_get_optional(&parts, index.clone()) {
    std::option::Option::None => Rc::new(Outcome::Accepted {
    value: acc.clone(),
    diagnostics: Box::new(std::option::Option::None),
}),
    Some(part) => crate::v2_std_diagnostic::bind_outcome(bash_fold_serialize_word_node(part.clone()), |spelling| bash_fold_serialize_word_parts_concatenated_from(v1_rt::concat(acc.clone(), spelling.clone()), parts.clone(), v1_rt::int_add(index.clone(), 1))),
}
    })
}

