pub fn bash_fold_serialize_andor_operand(stmt: Rc<Node>, group_binding: std::string::String, group_and_or: bool) -> Rc<Outcome<String>> {
    {
        let binding = bash_fold_built_stmt_production_binding(stmt.clone());
if (binding.clone() == "bash_build_stmt_negation".to_string()) {
            bash_fold_serialize_grouped_stmt(stmt.clone())
        } else {
            if (group_and_or.clone() && (binding.clone() == group_binding.clone())) {
                bash_fold_serialize_grouped_stmt(stmt.clone())
            } else {
                bash_fold_serialize_node(stmt.clone())
            }
        }
}
}

