pub fn bash_fold_serialize_negation_inner(inner: Rc<Node>) -> Rc<Outcome<String>> {
    {
        let binding = bash_fold_built_stmt_production_binding(inner.clone());
if (binding.clone() == "bash_production_fold_or_else".to_string()) {
            bash_fold_serialize_grouped_stmt(inner.clone())
        } else {
            if (binding.clone() == "bash_production_fold_and_then".to_string()) {
                bash_fold_serialize_grouped_stmt(inner.clone())
            } else {
                if (binding.clone() == "bash_production_fold_pipe".to_string()) {
                    bash_fold_serialize_grouped_stmt(inner.clone())
                } else {
                    if (binding.clone() == "bash_build_stmt_negation".to_string()) {
                        bash_fold_serialize_grouped_stmt(inner.clone())
                    } else {
                        bash_fold_serialize_node(inner.clone())
                    }
                }
            }
        }
}
}

pub fn bash_fold_serialize_negation_node(stmt: Rc<Node>) -> Rc<Outcome<String>> {
    match v1_rt::list_get_optional(&crate::v2_std_node::positional_child_target_nodes(stmt), 1) {
    Some(inner) => crate::v2_std_diagnostic::bind_outcome(bash_fold_serialize_negation_inner(inner.clone()), |inner_spelling| bash_fold_serialize_emit_from_node(bash_stmt_negation_emitted(), crate::v2_extdeps_languages_bash::bash_stmt_negation_target_model(inner_spelling))),
    std::option::Option::None => crate::v2_extdeps_languages_bash_command_fold::bash_fold_serialize_refused("bash_fold_serialize_positional_child_absent".to_string()),
}
}

pub fn bash_fold_serialize_node(stmt: Rc<Node>) -> Rc<Outcome<String>> {
    {
        let binding = bash_fold_built_stmt_production_binding(stmt.clone());
if (binding.clone() == "bash_production_fold_command".to_string()) {
            bash_fold_serialize_command_node(stmt.clone())
        } else {
            if (binding.clone() == "bash_production_fold_assign".to_string()) {
                bash_fold_serialize_assign_node(stmt.clone())
            } else {
                if (binding.clone() == "bash_production_fold_exit".to_string()) {
                    bash_fold_serialize_exit_node(stmt.clone())
                } else {
                    if (binding.clone() == "bash_production_fold_and_then".to_string()) {
                        bash_fold_serialize_and_then_node(stmt.clone())
                    } else {
                        if (binding.clone() == "bash_production_fold_or_else".to_string()) {
                            bash_fold_serialize_or_else_node(stmt.clone())
                        } else {
                            if (binding.clone() == "bash_production_fold_pipe".to_string()) {
                                bash_fold_serialize_pipe_node(stmt.clone())
                            } else {
                                if (binding.clone() == "bash_production_fold_if".to_string()) {
                                    bash_fold_serialize_if_node(stmt.clone())
                                } else {
                                    if (binding.clone() == "bash_build_stmt_if_else".to_string()) {
                                        bash_fold_serialize_if_else_node(stmt.clone())
                                    } else {
                                        if (binding.clone() == "bash_production_fold_subshell".to_string()) {
                                            bash_fold_serialize_subshell_node(stmt.clone())
                                        } else {
                                            if (binding.clone() == "bash_production_fold_with_redir".to_string()) {
                                                bash_fold_serialize_with_redir_node(stmt.clone())
                                            } else {
                                                if (binding.clone() == "bash_build_stmt_negation".to_string()) {
                                                    bash_fold_serialize_negation_node(stmt.clone())
                                                } else {
                                                    if (binding.clone() == "bash_production_fold_function_def".to_string()) {
                                                        bash_fold_serialize_function_def_node(stmt.clone())
                                                    } else {
                                                        if (binding.clone() == "bash_production_fold_seq".to_string()) {
                                                            bash_fold_serialize_seq_node(stmt.clone())
                                                        } else {
                                                            if (binding.clone() == "bash_production_fold_brace_group".to_string()) {
                                                                bash_fold_serialize_brace_group_node(stmt.clone())
                                                            } else {
                                                                if (binding.clone() == "bash_production_fold_comment".to_string()) {
                                                                    bash_fold_serialize_comment_node(stmt.clone())
                                                                } else {
                                                                    if (binding.clone() == "bash_production_fold_case".to_string()) {
                                                                        bash_fold_serialize_case_node(stmt.clone())
                                                                    } else {
                                                                        if (binding.clone() == "bash_production_fold_for".to_string()) {
                                                                            bash_fold_serialize_for_node(stmt.clone())
                                                                        } else {
                                                                            if (binding.clone() == "bash_production_fold_array_assign".to_string()) {
                                                                                bash_fold_serialize_array_assign_node(stmt.clone())
                                                                            } else {
                                                                                if (binding.clone() == "bash_build_refused_empty_stmt_list".to_string()) {
                                                                                    Rc::new(Outcome::Rejected {
    diagnostics: crate::v2_std_diagnostic::diagnostics_singleton(crate::v2_extdeps_languages_bash_command_fold::bash_fold_unsupported_variant_diagnostic("bash_build_refused_empty_stmt_list".to_string())),
})
                                                                                } else {
                                                                                    bash_fold_serialize_leaf_node(stmt.clone(), binding.clone(), "bash_relation_rule_fold_unsupported".to_string())
                                                                                }
                                                                            }
                                                                        }
                                                                    }
                                                                }
                                                            }
                                                        }
                                                    }
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
}
}

pub fn bash_fold_serialize_body(stmts: Rc<Vec<Rc<Node>>>) -> Rc<Outcome<String>> {
    stacker::maybe_grow(512 * 1024, 2 * 1024 * 1024, || {
        match crate::std_algebra::list_head(stmts.clone()) {
    std::option::Option::None => Rc::new(Outcome::Accepted {
    value: "".to_string(),
    diagnostics: Box::new(std::option::Option::None),
}),
    Some(s) => crate::v2_std_diagnostic::bind_outcome(bash_fold_serialize_node(s.clone()), |part| match crate::std_algebra::list_tail(stmts.clone()) {
    Some(t) => crate::v2_std_diagnostic::bind_outcome(bash_fold_serialize_body(t.clone()), |rest| Rc::new(Outcome::Accepted {
    value: v1_rt::concat(v1_rt::concat(part.clone(), "\n".to_string()), rest.clone()),
    diagnostics: Box::new(std::option::Option::None),
})),
    std::option::Option::None => Rc::new(Outcome::Accepted {
    value: v1_rt::concat(part.clone(), "\n".to_string()),
    diagnostics: Box::new(std::option::Option::None),
}),
}),
}
    })
}

pub fn bash_fold_serialize_program(stmts: Rc<Vec<Rc<Node>>>, set_e: bool) -> Rc<Outcome<String>> {
    crate::v2_std_diagnostic::bind_outcome(bash_fold_serialize_body(stmts), |body| if set_e.clone() {
        Rc::new(Outcome::Accepted {
    value: v1_rt::concat("set -e\n".to_string(), body.clone()),
    diagnostics: Box::new(std::option::Option::None),
})
    } else {
        Rc::new(Outcome::Accepted {
    value: body.clone(),
    diagnostics: Box::new(std::option::Option::None),
})
    })
}

